import{_ as i,C as r,o as n,c as h,j as d,a as e,E as o,a5 as c}from"./chunks/framework.BYIUCCsM.js";const P=JSON.parse('{"title":"徽标","description":"","frontmatter":{},"headers":[],"relativePath":"components/badge.md","filePath":"components/badge.md","lastUpdated":1787679442000}'),s={name:"components/badge.md"},b={id:"徽标",tabindex:"-1"};function p(u,t,m,g,x,f){const l=r("Badge",!0),a=r("XhDemo");return n(),h("div",null,[d("h1",b,[t[0]||(t[0]=e("徽标 ",-1)),o(l,{type:"info",text:"badge"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#徽标","aria-label":'Permalink to "徽标 <Badge type="info" text="badge" />"'},"​",-1))]),t[3]||(t[3]=c('<p>提醒你注意某个东西：它有几条未读、处在什么状态、是不是新的。 徽标说的是「有事情发生了」，不是「这是什么」——后者是<a href="./tag">标签</a>的活。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>计数角标：未读消息、购物车件数、待办条数。</li><li>小红点：只表示「有新的」，不说有几条。</li><li>状态提示：在线 / 离线、进行中、新。</li><li>附着在按钮、头像、标签页、菜单项上，报告那个东西的状态。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>表达「这是什么」——分类、技能、筛选条件：用<a href="./tag">标签</a>，它承载实体身份，还能被摘掉。</li><li>用户要点它来筛选或删除：徽标不接交互，那是标签的语义。</li><li>表达进度：用<a href="./progress">进度条</a>。</li><li>是一个可开关的选项：用<a href="./toggle">切换按钮</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>语气 · 尺寸两轴与其余组件同源；角标只有一种形态，没有形态轴。</li><li><code>placement</code> 决定挂在哪个角，四角可选，跟随文字方向。</li><li><code>count</code> 自己出数字，超过 <code>max</code>（默认 99）写成「99+」。</li><li>计数为 0 时整枚收起，要显示 0 就开 <code>showZero</code>。</li><li><code>dot</code> 收成一个圆点：只表示「有」，不表示「有几个」。</li><li><code>label</code> 给读屏一整句：光念「3」听不出是什么的 3。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="计数角标" tabindex="-1">计数角标 <a class="header-anchor" href="#计数角标" aria-label="Permalink to &quot;计数角标&quot;">​</a></h3><p>被标记的东西写进默认插槽，角标自己贴到它的角上；计数、上限截断与 0 值收起都归角标算</p>',10)),o(a,{src:"badge/01-basic"}),t[4]||(t[4]=d("h3",{id:"圆点与落点",tabindex:"-1"},[e("圆点与落点 "),d("a",{class:"header-anchor",href:"#圆点与落点","aria-label":'Permalink to "圆点与落点"'},"​")],-1)),t[5]||(t[5]=d("p",null,"dot 只表示「有」不表示「有几个」；placement 决定挂在哪个角，rtl 下 end 自动落到左边",-1)),o(a,{src:"badge/02-dot"}),t[6]||(t[6]=d("h3",{id:"语气与尺寸",tabindex:"-1"},[e("语气与尺寸 "),d("a",{class:"header-anchor",href:"#语气与尺寸","aria-label":'Permalink to "语气与尺寸"'},"​")],-1)),t[7]||(t[7]=d("p",null,"tone 决定用哪族颜色——角标现实里主要是未读红点与在线/离线点；size 换的是圆点直径、两位数时的最小宽度与字号",-1)),o(a,{src:"badge/03-tone-size"}),t[8]||(t[8]=c('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-badge&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhBadge</code> <code>XhBadgeIndicator</code> <code>XhBadgeRoot</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/badge.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;badge&quot;</code>：<strong><code>root</code></strong> · <code>indicator</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>count</code></td><td><code>number</code></td><td></td><td>计数。给了它角标就自己出数字，超过 max 写成「max+」。 与 indicator 的默认插槽二选一：插槽有内容时以插槽为准。</td></tr><tr><td><code>dot</code></td><td><code>boolean</code></td><td></td><td>只出一个点，不出数字。给了它 count 只用来决定显不显示。</td></tr><tr><td><code>label</code></td><td><code>string</code></td><td></td><td>读屏怎么念这枚角标。 角标挂在按钮、头像上时，光念数字听不出这是什么，得由宿主给出「3 条未读」这样的整句。</td></tr><tr><td><code>max</code></td><td><code>number</code></td><td></td><td>计数上限，默认 99：再多也只写 99+，免得角标被撑变形。</td></tr><tr><td><code>placement</code></td><td><code>BadgePlacement</code></td><td></td><td>挂在哪个角上，默认 top-end（右上角；rtl 下自动落到左上）。</td></tr><tr><td><code>showZero</code></td><td><code>boolean</code></td><td></td><td>计数为 0 时是否照样显示，默认不显示——没有未读就不该有角标。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。换的是圆点直径、两位数时的最小宽度与字号。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定用哪族颜色。 角标现实里主要用 danger（未读小红点）与 success / neutral（在线 / 离线点）。</td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhBadge</code></td><td><code>default</code></td><td>—</td><td></td></tr><tr><td><code>XhBadgeIndicator</code></td><td><code>default</code></td><td><code>{ text: string }</code></td><td></td></tr></tbody></table><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>connect</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>visible</code></td><td><code>boolean</code></td><td>此刻该不该渲染：计数为 0 且没开 showZero 时为假。</td></tr><tr><td><code>text</code></td><td><code>string</code></td><td>算好的显示文本：超过 max 的写成「99+」；dot 模式与无 count 时为空串。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>锚点：被标记的那个东西（按钮、头像、标签页）放进它里面。</td></tr><tr><td><code>getIndicatorProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>角标本身，绝对定位在 root 的某个角上。</td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>indicator</code></td><td><code>aria-label</code></td><td>props.label</td></tr><tr><td><code>indicator</code></td><td><code>role</code></td><td>&#39;status&#39; | undefined</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/badge.css</code> 按部件选择：<code>[data-scope=&quot;badge&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-placement</code></td><td>props.placement</td></tr><tr><td><code>indicator</code></td><td><code>data-dot</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>indicator</code></td><td><code>data-placement</code></td><td>props.placement</td></tr><tr><td><code>indicator</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>indicator</code></td><td><code>data-tone</code></td><td>props.tone</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-badge-bg</code> · <code>--xh-badge-dot-size</code> · <code>--xh-badge-fg</code> · <code>--xh-badge-font-size</code> · <code>--xh-badge-font-weight</code> · <code>--xh-badge-min-size</code> · <code>--xh-badge-px</code> · <code>--xh-badge-radius</code> · <code>--xh-badge-ring</code></p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像；另有按 <code>dir</code> 分支的规则。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>挂在<a href="./avatar">头像</a>、<a href="./button">按钮</a>、<a href="./tabs">标签页</a>的标签上做角标： 被标记的那个东西直接写进默认插槽，定位与偏移由组件自己承担，不必外层再套定位上下文。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>角标要给 <code>label</code>：读屏念到孤零零一个数字，用户不知道那是未读数还是别的。</li><li>状态别只用颜色区分：红绿色觉障碍的用户看不出差别，文字必须说清楚。</li><li>计数会变的地方交给 <code>count</code> 算，别自己拼「99+」——上限口径散在各处迟早不一致。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>拿徽标当分类标签用：它不可交互、摘不掉，用户点了没反应。</li><li>一屏里到处都是高饱和度的徽标：全都在喊，等于都没喊。</li><li>用徽标承载长句子。</li></ul>',35))])}const k=i(s,[["render",p]]);export{P as __pageData,k as default};
